#!/usr/bin/env python3
"""Normalize every manual chapter and append maintained r210 reference sections."""
import re
from pathlib import Path

from bs4 import BeautifulSoup
from manual_reference import appendix, create_graphics, figure

ROOT=Path(__file__).resolve().parents[1]


def user_update(lang):
    it=lang=='it'
    html='<section id="r210-workflows"><h2>'+('Metronomo a zone e strumenti personali' if it else 'Zone metronome and personal tools')+'</h2>'
    html+='<p>'+('Il metronomo a zone può iniziare dalla posizione corrente del transport, tramite il menu contestuale, oppure dalla posizione in millisecondi impostata nella finestra di creazione. Il primo beat coincide con l’inserimento; i marker successivi fanno ripartire la griglia. Il pre-roll aggiunge da 0 a 64 battute prima del punto richiesto; se necessario viene esteso l’inizio del progetto. Un limite Stop può silenziare la parte finale. Spostare, aggiungere, disabilitare o rimuovere un marker rigenera e salva il WAV a zone; waveform, cache e riproduzione vengono aggiornate. Le impostazioni manuali BPM/misura della zona seguono l’identità dei marker.' if it else 'Insert a zone metronome at the current transport position from the context menu, or enter an insertion position in milliseconds in its creation dialog. The first beat matches insertion; subsequent markers restart the grid. Pre-roll adds 0-64 bars before insertion, extending the project at the beginning when necessary. A Stop limit can mute the end. Moving, adding, disabling or removing a marker regenerates and saves the zone WAV, updating waveform, cache and playback. Manual zone BPM/meter settings follow marker identities.')+'</p>'
    html+=figure('metronome-'+lang+'.png','Creazione del metronomo: modo, griglia indipendente, inserimento e pre-roll.' if it else 'Metronome creation: mode, independent grid, insertion and pre-roll.')
    html+='<p>'+('I BPM audio cambiano la velocità del progetto; il comando Griglia modifica solo BPM e misura del metronomo, snap e visualizzazione musicale, lasciando inalterata la velocità delle tracce. Il metronomo adattivo deriva invece il tempo dall’audio. Delay/offset sono applicati anche alla riproduzione; le unità includono millisecondi, battiti, misure e misure:battiti. R rigenera metronomo o chords selezionati; B esegue Bounce to track. Lo snap e i bordi magnetici aiutano gli spostamenti senza introdurre sovrapposizioni sulla stessa traccia.' if it else 'Audio BPM changes project playback speed; Grid changes only metronome BPM/meter, snap and musical display, retaining track speed. Adaptive metronome timing is derived from audio instead. Delay/offset also affects playback; units include milliseconds, beats, bars and bars:beats. R regenerates the selected metronome/chords track; B bounces a track. Snap and magnetic edges guide movement without introducing overlaps on the same track.')+'</p>'
    html+=figure('context-'+lang+'.png','Menu per categoria: resta nella finestra e scorre se lo spazio è insufficiente.' if it else 'Categorized context menu: stays in the viewport and scrolls when necessary.')
    html+='<h3>'+('Barre strumenti e monitor Job AI' if it else 'Toolbars and AI monitor')+'</h3><p>'+('I pulsanti nelle barre orizzontali mostrano icone; il nome compare nel tooltip ed è disponibile alle tecnologie assistive. Il pulsante di configurazione della barra, disponibile anche da Impostazioni, apre l’elenco degli elementi: scegliere Transport e progetto oppure Strumenti di editing, trascinare o usare le frecce per riordinare e assegnare ciascun elemento a una delle sei righe. Salvare il layout; Ripristina default ripristina anche la posizione del monitor. Le righe vanno a capo sugli schermi stretti. Lo zoom della timeline conserva il tempo al centro della vista durante il trascinamento e al rilascio; pulsanti +/− e preset seguono lo stesso criterio, entro i limiti di scorrimento del progetto.' if it else 'Horizontal toolbar buttons show icons; names appear in tooltips and remain accessible to assistive technology. The toolbar configuration button, also available in Settings, opens the item list: choose Transport and project or Editing tools, drag or use arrows to reorder, and assign each item to one of six rows. Save the layout; Restore defaults also resets monitor position. Rows wrap on narrow screens. Timeline zoom retains the time at the view center while dragging and after release; +/− buttons and presets use the same anchor, within project scroll boundaries.')+'</p>'
    html+=figure('toolbar-'+lang+'.png','Riordino accessibile e scelta delle righe.' if it else 'Accessible reordering and row selection.')
    html+='<p>'+('Il monitor Job AI parte nel margine sinistro, sotto la navigazione. Trascinare la maniglia a puntini per spostarlo; con la maniglia a fuoco sono disponibili le frecce e Home per il ripristino. La posizione rimane nella finestra dopo il ridimensionamento. Sul server layout e posizione sono associati all’utente autenticato; nelle app native sono salvati nelle preferenze locali. Nel mixer Pan e Gain hanno etichette dedicate; FX apre gli effetti di canale o master.' if it else 'The AI monitor starts at the left margin, below navigation. Drag its dotted handle to move it; with the handle focused, arrow keys move it and Home resets it. Resizing keeps it in view. Server layout and position belong to the authenticated user; native apps store them in local preferences. Mixer Pan and Gain have dedicated labels; FX opens channel or master effects.')+'</p>'
    html+=figure('mixer-'+lang+'.png','Mixer aggiornato con Gain, Pan e FX.' if it else 'Updated mixer with Gain, Pan and FX.')
    html+='<h2>'+('Audio, VST3 e MIDI' if it else 'Audio, VST3 and MIDI')+'</h2><p>'+('Il motore corrente resta selezionabile. Il DSP C++ è disponibile sia nelle app native sia sul server; l’admin del server sceglie il motore nelle impostazioni Web App. Nel browser il flusso C++ usa una coda PCM in un worker dedicato e AudioWorklet; il trasporto nativo può usare il dispositivo locale. I VU mostrano livelli misurati. Un progetto complesso o un plugin lento può comunque causare underrun: usare la diagnostica e ridurre il carico.' if it else 'The Current engine remains selectable. C++ DSP is available in native apps and on the server; server administrators choose it under Web App settings. Browser C++ streaming uses a dedicated PCM worker queue and AudioWorklet; native transport can use the local device. VU meters show measured levels. Complex projects or slow plugins can still cause underruns: inspect diagnostics and reduce load.')+'</p><p>'+('Bounce to track applica il processing della traccia selezionata; Bounce project to track usa il mix master. I plugin VST3 richiedono binari compatibili con sistema e architettura del computer che li esegue, anche quando il client è remoto. Il catalogo opzionale permette installazione, avanzamento per plugin e disinstallazione controllata; i preset nei progetti non vengono cancellati. Un plugin in uso deve essere chiuso prima di rimuoverlo. Il manuale VST3 IT/EN dettaglia editor originale, VSTi, MIDI e sincronizzazione host.' if it else 'Bounce to track applies selected-track processing; Bounce project to track uses the master mix. VST3 plugins require binaries matching the OS/architecture of the processing computer, including remote use. The optional catalog provides installation, per-plugin progress and controlled uninstall; stored project presets are retained. Close active plugin instances before removing their package. The IT/EN VST3 manual details original editors, VSTi, MIDI and host synchronization.')+'</p>'
    html+='<p><a href="/docs/user/vst3'+('/en' if lang=='en' else '')+'">'+('Manuale VST3 online' if it else 'Online VST3 manual')+'</a> · <a href="/docs/pdf/vst3/'+lang+'">PDF VST3</a></p>'
    html+='<h2>'+('AI, consumi e abbonamenti' if it else 'AI, usage and subscriptions')+'</h2><p>'+('I motori AI del server passano dalla coda globale. Le app native usano un token per istanza remota, associato all’utente. Il centro Job AI permette di seguire stato, CPU/GPU, avanzamento e cancellazione anche con la finestra di origine chiusa. La notifica finale compare quando l’origine è chiusa e i risultati sono stati salvati nel progetto. Se SMTP è configurato, vengono inviate anche le notifiche previste per i job e i riepiloghi. Le stime GPU vengono identificate come tali; errori di misura non vanno confusi con un consumo nullo.' if it else 'Server AI engines use the global queue. Native apps use one token per remote instance, associated with a user. AI jobs exposes status, CPU/GPU, progress and cancellation even after closing the originating window. Completion notices appear when the origin is closed and results have been saved in the project. Configured SMTP enables job notifications and usage summaries. GPU estimates are identified as estimates; measurement errors must not be interpreted as zero usage.')+'</p>'
    html+='<p>'+('I consumi CPU/GPU accettati dal server sono contabilizzati per quote e billing. I contatori in corso restano separati fino alla chiusura e accettazione del job. Le evidenze di origine sono conservate per audit; dati mancanti o non validi non autorizzano addebiti.' if it else 'CPU/GPU consumption accepted by the server is accounted for quotas and billing. Live counters remain separate until job completion and acceptance. Source evidence is retained for audit; missing or invalid data does not authorize charges.')+'</p>'
    html+=figure('jobs-'+lang+'.png','Centro Job AI: stato, risorse e controlli anche in background.' if it else 'AI job center: status, resources and background controls.')
    html+='<p>'+('Nel profilo, Limiti e Quote raccoglie storage, CPU/GPU, consumi fatturabili e storico. Abbonamenti e crediti sono disponibili solo se abilitati dall’amministratore per l’utente. I crediti coprono extra-quota di un abbonamento attivo, non l’uso senza abbonamento. Un job ammesso termina anche se esaurisce i crediti durante l’esecuzione, senza ulteriori addebiti oltre il budget ammesso. Con crediti a zero e necessità di extra-quota il job viene rifiutato: acquistare crediti se abilitato oppure contattare l’admin. PayPal richiede configurazione server; non implica rinnovo automatico PayPal.' if it else 'Profile Limits and Quotas collects storage, CPU/GPU, billable usage and history. Subscriptions and credits are available only when enabled by the administrator for that user. Credits cover active-subscription overage, not use without a subscription. An admitted job completes even if its credits run out, without charges beyond its admitted budget. A job requiring overage credits is rejected when they are zero: purchase credits if enabled or contact an administrator. PayPal requires server configuration; it does not imply automatic PayPal renewal.')+'</p></section>'
    return html


def admin_update(lang):
    it=lang=='it'
    html='<section id="r210-workflows"><h2>'+('Gestione operativa r210' if it else 'r210 operational management')+'</h2>'
    html+='<p>'+('Impostazioni raccoglie Web App, utenti, diagnostica, SMTP, sicurezza, SSO e gestione delle risorse. La ricerca utenti trova dinamicamente nome, username o email. SMTP include una mail di prova: verificare recapito prima di affidarsi alle notifiche. Google, Facebook e GitHub restano disattivati finché configurati; l’identità SSO non sostituisce l’approvazione admin. Le nuove registrazioni richiedono verifica email, secondo fattore e approvazione secondo il flusso prescelto.' if it else 'Settings groups Web App, users, diagnostics, SMTP, security, SSO and resource management. User search dynamically matches name, username or email. SMTP includes a test email: verify delivery before relying on notifications. Google, Facebook and GitHub remain disabled until configured; SSO identity does not replace admin approval. New registration requires email verification, second factor and approval according to the chosen enrollment flow.')+'</p>'
    html+=figure('admin-settings.png','Interfaccia amministrativa su un server di prova senza dati personali.' if it else 'Administration interface on a disposable server without personal data.')
    html+='<h3>'+('Quote, piani, crediti e pagamenti' if it else 'Quotas, plans, credits and payments')+'</h3><p>'+('Le quote CPU/GPU/storage e le tariffe sono configurabili. I nuovi utenti hanno 5 GiB di storage; gli admin non hanno quota per default e non possono essere disabilitati o eliminati. Un utente senza abbonamenti attivabili mantiene l’accounting, senza billing né crediti. I crediti richiedono l’abilitazione globale e un abbonamento attivo/promo; gli admin possono assegnare promo e crediti manualmente. Le modifiche ai limiti della sottoscrizione attiva non azzerano il periodo né i consumi: per gli aumenti scegliere se gratuiti o a pagamento.' if it else 'CPU/GPU/storage quotas and rates are configurable. New users receive 5 GiB storage; admins have no default quota and cannot be disabled or deleted. A user ineligible for subscriptions retains accounting without billing or credits. Credits require the global option and an active/promo subscription; admins can grant promos and credits manually. Active-subscription limit changes retain the period and usage: increases require an explicit free/paid choice.')+'</p><p>'+('La cessazione può essere immediata; il canone viene proporzionato se il billing è abilitato. Gli extra storage sono calcolati sulla quota aggiunta a pagamento e sulla sua durata, non semplicemente sui byte occupati. Le estensioni gratuite restano identificate separatamente. Configurare tariffe e valore del credito nelle impostazioni e verificare i riepiloghi per intervallo. PayPal usa ordini e catture verificati dal server; gli eventuali rimborsi monetari da regolare non diventano automaticamente crediti.' if it else 'Termination can be immediate; the plan fee is prorated when billing is enabled. Storage extras follow paid additional allocated quota and its duration, not merely occupied bytes. Free extensions stay distinct. Configure rates/credit value and inspect period summaries. PayPal uses server-verified orders/captures; monetary refund adjustments are not automatically converted into credits.')+'</p>'
    html+=figure('admin-billing.png','Accounting e billing: verificare periodo, utente e origine delle misure.' if it else 'Accounting and billing: check period, user and measurement origin.')
    html+='<h3>'+('Runtime AI e GPU' if it else 'AI runtimes and GPU')+'</h3><p>'+('install_mta.sh installa i motori AI in runtime versionati sotto /opt/mta/ai-*. Servono al funzionamento: non cancellare manualmente il runtime attivo. La pulizia automatica deve conservare quelli riferiti dalla configurazione. Su EL10 FFmpeg può essere fornito da ffmpeg-free. I gruppi SAM Audio/torchcodec/xFormers devono corrispondere al backend CPU/CUDA/ROCm; pacchetti CUDA non compatibili non risolvono un ambiente ROCm. Diagnostica mostra installazione, sorgente delle misure, limiti artefatti e dettagli di errore.' if it else 'install_mta.sh installs AI engines into versioned /opt/mta/ai-* runtimes. These are needed at runtime: never manually delete the active environment. Automatic cleanup retains environments referenced by configuration. EL10 may provide FFmpeg through ffmpeg-free. SAM Audio/torchcodec/xFormers packages must match CPU/CUDA/ROCm; incompatible CUDA packages do not fix a ROCm environment. Diagnostics exposes installation status, measurement sources, artifact limits and error details.')+'</p><p>'+('In LXC la sola presenza di cgroup o della GPU non garantisce contatori per processo. L’agente host deve avere socket montato, autorizzazioni e compatibilità col kernel/driver. Un contatore a zero o non verificato deve conservare questo stato nei report. Prima del billing verificare origine e politica configurata per le stime. Non dichiarare la piattaforma certificata sulla sola base della CI.' if it else 'In LXC, cgroup/GPU availability alone does not guarantee per-process counters. The host agent needs a mounted socket, permissions and kernel/driver compatibility. Zero or unverified counters must retain that status in reports. Before billing, verify measurement origin and the configured estimate policy. CI alone does not certify a production platform.')+'</p>'
    html+='<h3>'+('DSP C++, VST3 e rete' if it else 'C++ DSP, VST3 and networking')+'</h3><p>'+('Il DSP C++ e i plugin VST3 sono disponibili sul server. Le build RPM/DEB/Docker includono il runtime; i plugin opzionali vengono compilati/installati separatamente nel catalogo gestito. Le licenze restano distinte e vanno riesaminate periodicamente. Un plugin in una sessione live o in un editor aperto non è disinstallabile. L’interfaccia originale remota richiede il backend display; la disponibilità del catalogo non equivale a compatibilità di tutti i plugin.' if it else 'C++ DSP and VST3 plugins are available on the server. RPM/DEB/Docker builds include the runtime; optional plugins are built/installed separately through the managed catalog. Licenses remain separate and need periodic review. A plugin used by a live session or open editor cannot be uninstalled. Original remote editors need the display backend; catalog presence does not imply all-plugin compatibility.')+'</p><p>'+('HAProxy/Ingress deve consentire streaming e WebSocket e non interrompere i job lunghi per timeout di proxy. Il server esegue DSP e AI, mentre il browser riproduce il PCM ricevuto: buffering di rete e tempo DSP sono metriche diverse. Verificare il trasporto reale dopo aggiornamenti del proxy, driver o plugin.' if it else 'HAProxy/Ingress must allow streaming/WebSockets and avoid interrupting long jobs through proxy timeouts. The server runs DSP/AI while the browser plays received PCM: network buffering and DSP time are different metrics. Validate real transport after proxy, driver or plugin updates.')+'</p>'
    html+='<h3>'+('Conservazione, dump e ripristino' if it else 'Retention, dumps and restore')+'</h3><p>'+('La cancellazione normale conserva accounting/billing e le identità non riciclabili; il grace period progetti è configurabile, con default 60 giorni. L’utente riceve il link all’archivio e la scadenza se SMTP è configurato. Negli Archivi utenti cancellati l’admin può cancellare definitivamente i dati con una conferma. Il percorso privacy con sandbox ha conservazione configurabile (default 365 giorni), salvo cancellazione definitiva esplicita. I dump possono selezionare utenti/progetti; un utente include tutti i suoi progetti. Provare un restore in un ambiente isolato prima di usarlo in produzione e mantenere una copia indipendente.' if it else 'Normal deletion retains accounting/billing and non-recyclable identities; project grace is configurable, default 60 days. Configured SMTP sends the archive link and expiry. Under deleted-user archives, admins can permanently remove remaining data with one confirmation. The privacy sandbox path has configurable retention (default 365 days) unless explicitly purged. Dumps can select users/projects; a user includes all their projects. Test restoration in isolation before production and retain an independent backup.')+'</p><p>'+('Privacy e termini vengono generati con i dati dell’istanza. Sono necessari Titolare, Paese, email assistenza/reclami, URL pubblica HTTPS e data di efficacia; i campi mancanti facoltativi vengono omessi. Le modifiche ai dati legali notificano gli utenti registrati se SMTP è configurato. I documenti standard richiedono comunque una verifica del gestore per il proprio trattamento e giurisdizione.' if it else 'Privacy/terms are generated from instance data. Required fields are controller, country, support/complaints email, public HTTPS URL and effective date; missing optional fields are omitted. Legal-data changes notify registered users when SMTP is configured. Standard documents still require operator review for actual processing and jurisdiction.')+'</p></section>'  # noqa: S608 -- static trusted HTML, no SQL execution
    return html


def update():
    create_graphics()
    for role in ('user','admin'):
        for lang in ('it','en'):
            name=role+('-en' if lang=='en' else '')+'.html';path=ROOT/'app/docs'/name
            soup=BeautifulSoup(path.read_text(),'html.parser');body=soup.body;wrap=soup.select_one('.wrap')
            for old in soup.select('#r210-workflows,#technical-appendix'):old.decompose()
            # Historical chapters after </div> had escaped the .wrap typography.
            for node in list(body.contents):
                if node is not wrap:wrap.append(node.extract())
            content=user_update(lang) if role=='user' else admin_update(lang)
            for node in list(BeautifulSoup(content+appendix(lang),'html.parser').contents):wrap.append(node)
            for heading_index,h in enumerate(soup.select('h2'),1):
                if h.find_parent(class_='technical-appendix'):continue
                if not h.get('id') or h['id'].startswith('chapter-'):h['id']='chapter-'+str(heading_index)
            headings=[h for h in soup.select('h2') if not h.find_parent(class_='technical-appendix')]
            for n,h in enumerate(headings,1):
                for child in list(h.contents):child.extract()
                # Filled below from retained original text, rather than generated numbering.
            # Reparse retained source titles: removing a number never discards wording.
            source=BeautifulSoup(path.read_text(),'html.parser')
            original=[h.get_text(' ',strip=True) for h in source.select('h2') if not h.find_parent(id='r210-workflows') and not h.find_parent(id='technical-appendix')]
            fresh=BeautifulSoup(content,'html.parser').select('h2')
            titles=original+[h.get_text(' ',strip=True) for h in fresh]
            for n,(h,title) in enumerate(zip(headings,titles),1):h.string=str(n)+'. '+re.sub(r'^\d+\.\s*','',title)
            toc=soup.select_one('.toc .cols')
            if toc:
                toc.clear()
                for h in soup.select('h2'):
                    a=soup.new_tag('a',href='#'+(h.get('id') or 'technical-appendix'));a.string=h.get_text(' ',strip=True);toc.append(a)
            cover=soup.select_one('.cover')
            if cover:
                for old in cover.select('.manual-cover-metadata'):old.decompose()
                meta=soup.new_tag('div',attrs={'class':'manual-cover-metadata'})
                meta.append(BeautifulSoup('<b>MTA Audio Editor __VERSION__-r__REVISION__</b><br>Build: __BUILD__<br>Alessandro De Salvo<br>braket71@gmail.com<br>https://github.com/desalvo/mta-audio-editor<br>EUPL-1.2','html.parser'))
                cover.append(meta)
            css=soup.select_one('link[rel="stylesheet"]');css['href']='/static/docs-assets/doc.css?v=0.3.0-r210-zones-layout'
            text=str(soup)
            text=text.replace('Wait for buffering/synchronization; the delay is intentional to keep tracks aligned.','Inspect the reported preparation stage and source format; cached compatible audio should start promptly. For C++ inspect underruns and network buffering.')
            text=text.replace('Attendere buffering/sincronizzazione: il ritardo è intenzionale per mantenere le tracce allineate.','Controllare fase di preparazione e formato sorgente; le sorgenti compatibili in cache devono partire rapidamente. Per C++ verificare underrun e buffering di rete.')
            text=text.replace("Attendi la fase di buffering e sincronizzazione: è intenzionale per mantenere le tracce allineate.","Controllare la fase di preparazione e il formato sorgente; l’audio compatibile in cache deve partire rapidamente. Per C++ controllare underrun e buffering di rete.")
            text=text.replace("Prima del Play tutte le tracce vengono preparate e bufferizzate. L'interfaccia mostra Buffering audio... attendere e poi Sincronizzazione tracce... attendere. Solo quando le sorgenti sono pronte viene eseguita la partenza comune. Durante il Play il clock di riferimento controlla eventuali derive e riallinea le sorgenti quando necessario.","Prima del Play vengono preparate le sorgenti necessarie. L’interfaccia distingue caricamento, decodifica, conversione e connessione del flusso, riportando traccia e avanzamento quando disponibili. Il motore corrente riusa i buffer compatibili in cache; il C++ server legge blocchi PCM con buffering adattivo nel browser. Il clock audio mantiene le tracce allineate. Minuti di attesa richiedono diagnostica e non rappresentano un normale ritardo intenzionale.")
            text=text.replace("Before playback, all tracks are prepared and buffered. The UI reports Buffering audio... please wait and then synchronization. Playback starts only when sources are ready. A reference clock monitors drift and realigns active sources when necessary.","Playback prepares the required sources. Preparation distinguishes loading, decoding, conversion and stream connection, with track/progress information when available. Current engine reuses compatible cached buffers; C++ server playback reads PCM blocks with adaptive browser buffering. The audio clock maintains track alignment. Waiting for minutes needs diagnosis and is not a normal intentional delay.")
            text=text.replace("Separate client-side track playback with buffering/synchronization.","Current: client track buffers. C++ server: PCM stream with adaptive buffering.")
            text=text.replace("Riproduzione separata delle tracce lato client con buffering/sincronizzazione.","Motore corrente: buffer delle tracce nel client. Server C++: flusso PCM con buffering adattivo.")
            path.write_text(text)
    print('Normalized 4 online manuals; shared appendices and graphics updated.')


if __name__=='__main__':update()
